import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); PrintWriter out = new PrintWriter(System.out); while (t-- > 0) { st = new StringTokenizer(br.readLine()); int a = Integer.parseInt(st.nextToken()); int b = Integer.parseInt(st.nextToken()); int c = Integer.parseInt(st.nextToken()); int p = Integer.parseInt(st.nextToken()); int q = Integer.parseInt(st.nextToken()); int r = Integer.parseInt(st.nextToken()); double totalVotes = p + q + r; double threshold = totalVotes / 2.0; int option1 = p + b + c; int option2 = a + q + c; int option3 = a + b + r; int option0 = a + b + c; if (option1 > threshold || option2 > threshold || option3 > threshold || option0 > threshold) { out.println("YES"); } else { out.println("NO"); } } out.flush(); out.close(); } }